-- Ephemeral OIN catalog research matrix.
--
-- This is reproducible experiment input for disposable lab applications. It is
-- not persistent simulated-environment desired state and must never be consumed by
-- environment deployment.

CREATE TABLE matrix_metadata (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);

INSERT INTO matrix_metadata (key, value) VALUES ('schema_version', '3');

CREATE TABLE oin_probe_cases (
    case_id TEXT PRIMARY KEY,
    app_key TEXT NOT NULL,
    variant TEXT NOT NULL,
    sign_on_mode TEXT NOT NULL CHECK (sign_on_mode = 'SAML_2_0'),
    settings_app_json TEXT NOT NULL,
    readiness TEXT NOT NULL CHECK (readiness IN ('ready', 'discovery', 'blocked')),
    purpose TEXT NOT NULL,
    evidence TEXT NOT NULL
);

-- Active tracing details stay separate so the broad catalog matrix retains its
-- compact, stable row contract. Values are synthetic public research inputs.
CREATE TABLE oin_probe_active_options (
    case_id TEXT PRIMARY KEY,
    app_link_label_suffix TEXT,
    assignment_profile_json TEXT NOT NULL DEFAULT '{}',
    FOREIGN KEY (case_id) REFERENCES oin_probe_cases (case_id)
);

