-- Public popularity evidence is kept separate from executable probes. Reported
-- product names are brands, not stable Okta catalog keys, and must be resolved
-- against a dated catalog inventory before an app is selected for testing.
CREATE TABLE popular_app_reports (
    report_year INTEGER NOT NULL,
    cohort TEXT NOT NULL,
    source_url TEXT NOT NULL,
    source_notes TEXT NOT NULL,
    PRIMARY KEY (report_year, cohort)
);

CREATE TABLE popular_app_report_entries (
    report_year INTEGER NOT NULL,
    cohort TEXT NOT NULL,
    report_name TEXT NOT NULL,
    rank INTEGER,
    growth_percent INTEGER,
    PRIMARY KEY (report_year, cohort, report_name),
    FOREIGN KEY (report_year, cohort)
        REFERENCES popular_app_reports (report_year, cohort)
);

