CREATE TABLE popular_app_catalog_targets (
    target_id TEXT PRIMARY KEY,
    report_name TEXT NOT NULL,
    app_key TEXT,
    catalog_display_name TEXT,
    observed_sign_on_modes_json TEXT NOT NULL,
    disposition TEXT NOT NULL CHECK (
        disposition IN ('saml_candidate', 'non_saml', 'absent')
    ),
    match_basis TEXT NOT NULL CHECK (
        match_basis IN ('exact_display', 'rebrand', 'brand_variant', 'no_current_match')
    ),
    notes TEXT NOT NULL
);

